    @Test func compressed() {
        let mismatches = Mismatches("portCompressedI64InVectorCode")
        let aInputs = Inputs.vectors(H.self, seed: 0x07D5_ADFC_777E_89B9)
        let maskInputs = Inputs.masks(H.Mask.self, seed: 0x07D5_ACFC_777E_8806)
        for (a, mask) in everyPair(aInputs, maskInputs) {
            let port = { () -> SIMD<Int64> in
                var a = a
                var mask = mask
                return withUnsafeTemporaryAllocation(of: SIMD<Int64>.self, capacity: 1) { result in
                    unsafe portCompressedI64InVectorCode(
                        result.baseAddress.unsafelyUnwrapped,
                        &a,
                        where: &mask
                    )
                    return unsafe result.baseAddress.unsafelyUnwrapped.move()
                }
            }()
            let reference = { () -> SIMD<Int64> in
                var a = a
                var mask = mask
                return withUnsafeTemporaryAllocation(of: SIMD<Int64>.self, capacity: 1) { result in
                    unsafe highwayCompressedI64InVectorCode(
                        result.baseAddress.unsafelyUnwrapped,
                        &a,
                        where: &mask
                    )
                    return unsafe result.baseAddress.unsafelyUnwrapped.move()
                }
            }()
            let checkedLanes =
                HighwayReference.compressTailIsDeterministicI64() ? H.laneCount : H.trueCount(mask)
            mismatches.check(
                (0..<checkedLanes).map { port.simd[$0] },
                (0..<checkedLanes).map { reference.simd[$0] },
                "a: \(describe(a)), mask: \(describe(mask))"
            )
        }
        mismatches.record()
    }

